import classNames from 'classnames';
import { isNumber } from 'lodash';
import React, { FunctionComponent, memo, ReactNode } from 'react';

import { TranslatedString } from '@bigcommerce/checkout/locale';
import { useCheckout } from '@bigcommerce/checkout/payment-integration-api';

import { ShopperCurrency } from '../currency';

export interface OrderSummaryItemProps {
    id: string | number;
    amount: number;
    quantity: number;
    name: string;
    amountAfterDiscount?: number;
    image?: ReactNode;
    description?: ReactNode;
    productOptions?: OrderSummaryItemOption[];
    quantityBackordered?: number;
    quantityOnHand?: number;
    backorderMessage?: string;
    showBackorderDetails?: boolean;
}

export interface OrderSummaryItemOption {
    testId: string;
    content: ReactNode;
    name?: string;
    value?: string;
    isMainBundledItem?: boolean;
    stockPosition?: {
        quantityBackordered?: number;
        quantityOnHand?: number;
        backorderMessage?: string;
    };
}

const OrderSummaryItemBackorderDetails = ({
    isExpanded,
    quantityBackordered,
    quantityOnHand,
    backorderMessage,
}: {
    isExpanded: boolean;
    quantityBackordered?: number;
    quantityOnHand?: number;
    backorderMessage?: string;
}) => {
    const { checkoutState } = useCheckout();
    const config = checkoutState.data.getConfig();

    const inventorySettings = config?.inventorySettings;
    const showQuantityOnBackorder = !!inventorySettings?.showQuantityOnBackorder;
    const showQuantityOnHand = !!inventorySettings?.showQuantityOnHand;
    const showBackorderMessage = !!inventorySettings?.showBackorderMessage;
    const shouldDisplayBackorderMessagesOnStorefront =
        !!inventorySettings?.shouldDisplayBackorderMessagesOnStorefront;

    if (!shouldDisplayBackorderMessagesOnStorefront) {
        return null;
    }

    const shouldDisplayQuantityOnHand = showQuantityOnHand && !!quantityOnHand && !!quantityBackordered;
    const shouldDisplayQuantityOnBackorder = showQuantityOnBackorder && !!quantityBackordered;
    const shouldDisplayBackorderMessage =
        showBackorderMessage && !!backorderMessage && !!quantityBackordered;

    if (!shouldDisplayQuantityOnHand && !shouldDisplayQuantityOnBackorder && !shouldDisplayBackorderMessage) {
        return null;
    }

    return (
        <div className="product-backorder-details-container" data-test="backorder-details">
            {isExpanded && shouldDisplayQuantityOnHand && (
                <div className="backorder-details-item" data-test="cart-item-onhand-qty">
                    <TranslatedString data={{ quantity: quantityOnHand }} id="cart.backorder_on_hand_text" />
                </div>
            )}
            {isExpanded && shouldDisplayQuantityOnBackorder && (
                <div className="backorder-details-item" data-test="cart-item-backorder-qty">
                    <TranslatedString data={{ quantity: quantityBackordered }} id="cart.backorder_quantity_text" />
                </div>
            )}
            {isExpanded && shouldDisplayBackorderMessage && (
                <div
                    className="backorder-details-item backorder-details-item--message"
                    data-test="cart-item-backorder-message"
                >
                    {backorderMessage}
                </div>
            )}
        </div>
    );
};

const OrderSummaryItem: FunctionComponent<OrderSummaryItemProps> = ({
    amount,
    amountAfterDiscount,
    image,
    name,
    productOptions,
    quantity,
    description,
    quantityBackordered,
    quantityOnHand,
    backorderMessage,
    showBackorderDetails,
}) => (
    <div className="product" data-test="cart-item">
        <figure className="product-column product-figure">{image}</figure>

        <div className="product-column product-body">
            <h4
                className="product-title optimizedCheckout-contentPrimary"
                data-test="cart-item-product-title"
            >
                {`${quantity} x ${name}`}
            </h4>
            {productOptions && productOptions.length > 0 && (
                <ul
                    className="product-options optimizedCheckout-contentSecondary"
                    data-test="cart-item-product-options"
                >
                    {productOptions.map((option, index) => (
                        <li className="product-option" data-test={option.testId} key={index}>
                            {option.name ? (
                                <>
                                    <span className={option.isMainBundledItem ? 'body-bold' : ''}>
                                        {option.name}
                                    </span>{' '}
                                    <span>{option.value}</span>
                                </>
                            ) : (
                                option.content
                            )}
                            {option.stockPosition && (
                                <OrderSummaryItemBackorderDetails
                                    backorderMessage={option.stockPosition.backorderMessage}
                                    isExpanded={!!showBackorderDetails}
                                    quantityBackordered={option.stockPosition.quantityBackordered}
                                    quantityOnHand={option.stockPosition.quantityOnHand}
                                />
                            )}
                        </li>
                    ))}
                </ul>
            )}
            {description && (
                <div
                    className="product-description optimizedCheckout-contentSecondary"
                    data-test="cart-item-product-description"
                >
                    {description}
                </div>
            )}
            <OrderSummaryItemBackorderDetails
                backorderMessage={backorderMessage}
                isExpanded={!!showBackorderDetails}
                quantityBackordered={quantityBackordered}
                quantityOnHand={quantityOnHand}
            />
        </div>

        <div className="product-column product-actions">
            <div
                className={classNames('product-price', 'optimizedCheckout-contentPrimary', {
                    'product-price--beforeDiscount':
                        isNumber(amountAfterDiscount) && amountAfterDiscount !== amount,
                })}
                data-test="cart-item-product-price"
            >
                <ShopperCurrency amount={amount} />
            </div>

            {isNumber(amountAfterDiscount) && amountAfterDiscount !== amount && (
                <div className="product-price" data-test="cart-item-product-price--afterDiscount">
                    <ShopperCurrency amount={amountAfterDiscount} />
                </div>
            )}
        </div>
    </div>
);

export default memo(OrderSummaryItem);
